ABSENT = [
    "How do trapped-ion qubits correct quantum phase errors?", "What is the orbital maneuver for a satellite Doppler shift?",
    "How do I tune a laser for Raman spectroscopy?", "Which finite-element mesh models turbine blade flutter?",
    "How is a protein crystal refined from X-ray diffraction?", "Which isotope ratio identifies an ancient meteorite?",
    "How do stereo cameras estimate underwater reef depth?", "What antenna geometry improves deep-space telemetry gain?",
    "How is a combustion flame front stabilized in a jet engine?", "Which acoustic filter removes echoes in a concert hall?",
    "How do cryogenic detectors measure dark matter recoil?", "What soil chemistry predicts phosphate uptake in wheat?",
    "How can an MRI sequence reduce magnetic susceptibility artifacts?", "Which star catalog measures galactic proper motion?",
    "How does a molten-salt reactor regulate neutron flux?", "Which lithography mask corrects silicon wafer diffraction?",
    "How is a marine propeller cavitation threshold calculated?", "What telescope aperture resolves an exoplanet transit?",
    "How does a seismic inversion estimate mantle density?", "Which electrochemical cell measures lithium diffusion?",
    "How do glacier cores reveal prehistoric atmospheric carbon?", "What aerodynamic profile reduces helicopter rotor noise?",
    "How can a radio interferometer image a pulsar?", "Which chromatography gradient separates peptide fragments?",
]

# These two authoring candidates overlap the artifact and vector-input topics;
# exclude them before freezing, encoding, or inspecting any test result.
TOPICS = [topic for topic in TOPICS if topic[0] not in {"determinism", "body-limit"}]


def build():
    assert len(TOPICS) == 60 and len(ABSENT) == 24
    # Hash-order is selected before running the encoder. Whole intent groups stay
    # together. This is a retrieval test: all public documents remain indexed.
    ordered = sorted((t[0] for t in TOPICS), key=lambda key: hashlib.sha256((VERSION + key).encode()).hexdigest())
    splits = {key: "development" if i < 36 else "calibration" if i < 48 else "test" for i, key in enumerate(ordered)}
    documents, queries, absent_i = [], [], 0
    for i, (key, title, body, title_b, body_b, literal, paraphrase, challenge) in enumerate(TOPICS):
        a, b = f"discussion-{i + 1:03d}-a", f"discussion-{i + 1:03d}-b"
        for doc_id, heading, text in [(a, title, body), (b, title_b, body_b)]:
            documents.append({"id": doc_id, "group": key, "title": heading, "text": text, "category": "Engineering discussion"})
        for kind, text, relevance in [("literal", literal, {a: 2, b: 1}), ("paraphrase", paraphrase, {a: 2, b: 1})]:
            queries.append({"id": f"{key}-{kind}", "group": key, "split": splits[key], "slice": kind, "text": text, "relevance": relevance})
        if i % 5 < 2:
            challenge, relevance, kind = ABSENT[absent_i], {}, "no_answer"
            absent_i += 1
        else:
            relevance, kind = {b: 2, a: 1}, "distractor"
        queries.append({"id": f"{key}-{kind}", "group": key, "split": splits[key], "slice": kind, "text": challenge, "relevance": relevance})
    provenance = {
        "version": VERSION, "language": "en", "created": "2026-10-10",
        "origin": "AI-authored fictional technical discussions; no production posts or visitor data.",
        "labels": "Author-assigned: 2 direct answer, 1 supporting context, 0 unjudged/unrelated. No independent human review is claimed.",
        "limitations": "Small synthetic English fixture with sparse topic-pair judgements; not a production-quality or safety certification.",
        "split_policy": "SHA256(version + intent group), first 36 development, next 12 calibration, final 12 test. All three rewrites remain together.",
    }
    ROOT.joinpath("data").mkdir(exist_ok=True)
    for name, value in [("corpus-v1.json", {"provenance": provenance, "documents": documents}), ("queries-v1.json", {"provenance": provenance, "queries": queries})]:
        ROOT.joinpath("data", name).write_text(json.dumps(value, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    frozen = {"version": VERSION, "groups": {split: sorted(k for k, v in splits.items() if v == split) for split in ("development", "calibration", "test")}, "sha256": {name: hashlib.sha256(ROOT.joinpath("data", name).read_bytes()).hexdigest() for name in ("corpus-v1.json", "queries-v1.json")}}
    ROOT.joinpath("frozen-v1.json").write_text(json.dumps(frozen, indent=2) + "\n", encoding="utf-8")
    print(f"Frozen {len(documents)} discussions and {len(queries)} grouped queries.")


if __name__ == "__main__":
    build()
